// HasDiagram applies the HasEdge predicate on the "diagram" edge.
func HasDiagram() predicate.DiagramRegion {
	return predicate.DiagramRegion(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DiagramTable, DiagramColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDiagramWith applies the HasEdge predicate on the "diagram" edge with a given conditions (other predicates).
func HasDiagramWith(preds ...predicate.Diagram) predicate.DiagramRegion {
	return predicate.DiagramRegion(func(s *sql.Selector) {
		step := newDiagramStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

